#include <iostream>
using namespace std;

int linearSearch(int a[], int n, int target, int& checks) {
    for (int i = 0; i < n; i++) {
        checks++;
        if (a[i] == target) {
            return i;
        }
    }
    return -1;
}

int countPairs(int n) {
    int steps = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            steps++;
        }
    }
    return steps;
}

int main() {
    int a[6] = {12, 5, 8, 21, 3, 17};
    int best = 0;
    linearSearch(a, 6, 12, best);
    int worst = 0;
    linearSearch(a, 6, 40, worst);
    cout << "Best case: " << best << " check, worst case: " << worst << " checks" << endl;
    cout << "Two nested loops over 6 items: " << countPairs(6) << " steps" << endl;
    return 0;
}
